DROP TABLE IF EXISTS `appointments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `appointments` (
  `id` varchar(191) NOT NULL,
  `customerId` varchar(191) NOT NULL,
  `astrologerProfileId` varchar(191) NOT NULL,
  `birthProfileId` varchar(64) DEFAULT NULL,
  `consultationType` varchar(32) NOT NULL DEFAULT 'CHAT',
  `scheduledDate` date NOT NULL,
  `scheduledTimeSlot` varchar(32) NOT NULL,
  `durationMinutes` int(11) NOT NULL DEFAULT 15,
  `ratePaisePerMinute` int(11) NOT NULL,
  `totalAmountPaise` bigint(20) NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `notes` text DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `appointments_customerId_status_idx` (`customerId`,`status`),
  KEY `appointments_astrologerProfileId_scheduledDate_scheduledTime_idx` (`astrologerProfileId`,`scheduledDate`,`scheduledTimeSlot`),
  CONSTRAINT `appointments_astrologerProfileId_fkey` FOREIGN KEY (`astrologerProfileId`) REFERENCES `astrologer_profiles` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `appointments_customerId_fkey` FOREIGN KEY (`customerId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
