CREATE TABLE `astrologer_bank_accounts` (
  `id` varchar(191) NOT NULL,
  `astrologerProfileId` varchar(191) NOT NULL,
  `accountHolderName` varchar(120) NOT NULL,
  `bankName` varchar(120) NOT NULL,
  `accountNumberMasked` varchar(64) NOT NULL,
  `ifscCode` varchar(32) NOT NULL,
  `upiId` varchar(120) DEFAULT NULL,
  `isVerified` tinyint(1) NOT NULL DEFAULT 0,
  `verifiedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `accountType` varchar(32) NOT NULL DEFAULT 'SAVINGS',
  `isPrimary` tinyint(1) NOT NULL DEFAULT 1,
  `panNumber` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `astrologer_bank_accounts_astrologerProfileId_key` (`astrologerProfileId`),
  CONSTRAINT `astrologer_bank_accounts_astrologerProfileId_fkey` FOREIGN KEY (`astrologerProfileId`) REFERENCES `astrologer_profiles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
