DROP TABLE IF EXISTS `astrologer_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `astrologer_documents` (
  `id` varchar(191) NOT NULL,
  `applicationId` varchar(191) DEFAULT NULL,
  `astrologerProfileId` varchar(191) DEFAULT NULL,
  `type` varchar(64) NOT NULL,
  `title` varchar(191) NOT NULL,
  `fileUrl` varchar(512) NOT NULL,
  `fileSize` int(11) DEFAULT NULL,
  `mimeType` varchar(64) DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `verificationNotes` text DEFAULT NULL,
  `verifiedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `astrologer_documents_applicationId_status_idx` (`applicationId`,`status`),
  KEY `astrologer_documents_astrologerProfileId_idx` (`astrologerProfileId`),
  CONSTRAINT `astrologer_documents_applicationId_fkey` FOREIGN KEY (`applicationId`) REFERENCES `astrologer_applications` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `astrologer_documents_astrologerProfileId_fkey` FOREIGN KEY (`astrologerProfileId`) REFERENCES `astrologer_profiles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

