  `userId` varchar(191) NOT NULL,
  `slug` varchar(140) NOT NULL,
  `displayName` varchar(120) NOT NULL,
  `verificationStage` enum('APPLIED','DOC_VERIFICATION','INTERVIEW','APPROVED','TRAINING','ACTIVE','REJECTED','SUSPENDED') NOT NULL DEFAULT 'APPLIED',
  `availabilityStatus` enum('OFFLINE','ONLINE','BUSY') NOT NULL DEFAULT 'OFFLINE',
  `chatEnabled` tinyint(1) NOT NULL DEFAULT 0,
  `audioEnabled` tinyint(1) NOT NULL DEFAULT 0,
  `videoEnabled` tinyint(1) NOT NULL DEFAULT 0,
  `experienceYears` int(11) NOT NULL DEFAULT 0,
  `bio` text DEFAULT NULL,
  `qualifications` text DEFAULT NULL,
  `chatRatePaise` int(11) NOT NULL DEFAULT 0,
  `audioRatePaise` int(11) NOT NULL DEFAULT 0,
  `videoRatePaise` int(11) NOT NULL DEFAULT 0,
  `commissionBpsOverride` int(11) DEFAULT NULL,
