  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `averageRating` double NOT NULL DEFAULT 4.9,
  `isLiveStreaming` tinyint(1) NOT NULL DEFAULT 0,
  `isOnline` tinyint(1) NOT NULL DEFAULT 0,
  `languagesJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`languagesJson`)),
  `lastHeartbeatAt` datetime(3) DEFAULT NULL,
  `specialisationsJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`specialisationsJson`)),
  `totalConsultations` int(11) NOT NULL DEFAULT 0,
  `totalMinutesConsulted` int(11) NOT NULL DEFAULT 0,
  `totalReviews` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `astrologer_profiles_userId_key` (`userId`),
  UNIQUE KEY `astrologer_profiles_slug_key` (`slug`),
  KEY `astrologer_profiles_verificationStage_availabilityStatus_idx` (`verificationStage`,`availabilityStatus`),
  KEY `astrologer_profiles_isOnline_verificationStage_idx` (`isOnline`,`verificationStage`),
  CONSTRAINT `astrologer_profiles_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
