--
-- Table structure for table `birth_profiles`
--

DROP TABLE IF EXISTS `birth_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `birth_profiles` (
  `id` varchar(191) NOT NULL,
  `userId` varchar(191) NOT NULL,
  `relation` varchar(32) NOT NULL DEFAULT 'SELF',
  `fullName` varchar(120) NOT NULL,
  `gender` varchar(20) DEFAULT NULL,
  `dateOfBirth` date NOT NULL,
  `timeOfBirth` varchar(16) DEFAULT NULL,
  `isBirthTimeUnknown` tinyint(1) NOT NULL DEFAULT 0,
  `birthPlace` varchar(191) NOT NULL,
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `timezone` varchar(64) DEFAULT 'Asia/Kolkata',
  `maritalStatus` varchar(32) DEFAULT NULL,
  `isDefault` tinyint(1) NOT NULL DEFAULT 0,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `birth_profiles_userId_isDefault_idx` (`userId`,`isDefault`),
  CONSTRAINT `birth_profiles_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

