CREATE TABLE `consultation_holds` (
  `id` varchar(191) NOT NULL,
  `consultationId` varchar(191) NOT NULL,
  `customerId` varchar(191) NOT NULL,
  `ratePaisePerMinute` int(11) NOT NULL,
  `heldAmountPaise` bigint(20) NOT NULL,
  `settledAmountPaise` bigint(20) NOT NULL DEFAULT 0,
  `status` varchar(32) NOT NULL DEFAULT 'ACTIVE',
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `settledAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `consultation_holds_consultationId_key` (`consultationId`),
  KEY `consultation_holds_customerId_status_idx` (`customerId`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
