  `position` int(11) NOT NULL DEFAULT 1,
  `status` varchar(32) NOT NULL DEFAULT 'WAITING',
  `estimatedWaitMinutes` int(11) NOT NULL DEFAULT 5,
  `joinedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `servicedAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `consultation_queues_astrologerProfileId_status_position_idx` (`astrologerProfileId`,`status`,`position`),
  CONSTRAINT `consultation_queues_astrologerProfileId_fkey` FOREIGN KEY (`astrologerProfileId`) REFERENCES `astrologer_profiles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
