  `acceptedAt` datetime(3) DEFAULT NULL,
  `channelName` varchar(128) DEFAULT NULL,
  `concern` varchar(120) DEFAULT NULL,
  `durationSeconds` int(11) NOT NULL DEFAULT 0,
  `endedAt` datetime(3) DEFAULT NULL,
  `expiresAt` datetime(3) DEFAULT NULL,
  `preferredLanguage` varchar(32) DEFAULT NULL,
  `rating` int(11) DEFAULT NULL,
  `rejectedAt` datetime(3) DEFAULT NULL,
  `rejectionReason` varchar(191) DEFAULT NULL,
  `review` text DEFAULT NULL,
  `startedAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `consultation_requests_customerId_status_idx` (`customerId`,`status`),
  KEY `consultation_requests_astrologerProfileId_status_idx` (`astrologerProfileId`,`status`),
  CONSTRAINT `consultation_requests_astrologerProfileId_fkey` FOREIGN KEY (`astrologerProfileId`) REFERENCES `astrologer_profiles` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `consultation_requests_customerId_fkey` FOREIGN KEY (`customerId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
