INSERT INTO `custom_roles` VALUES ('cmwxmq7f5000jn8fqwi92mrre','Business Owner','BUSINESS_OWNER','Full enterprise ownership with irrevocable administrative access','[\"*\"]',1,'2026-11-26 14:10:02.898','2026-11-26 14:10:02.898'),('cmwxmq7fz000kn8fqwmdac9cy','Super Administrator','SUPER_ADMIN','Complete operational management across all departments','[\"customer:view\",\"customer:edit\",\"customer:suspend\",\"astrologer:view\",\"astrologer:approve\",\"astrologer:rates\",\"staff:view\",\"staff:create\",\"staff:edit\",\"staff:roles\",\"finance:view\",\"finance:payout_approve\",\"finance:refund\",\"puja:manage\",\"store:manage\",\"cms:manage\",\"audit:view\"]',1,'2026-11-26 14:10:02.928','2026-11-26 14:10:02.928'),('cmwxmq7ge000ln8fq6nzwsjn0','Operations Manager','OPERATIONS_MANAGER','Oversees live calling, consultation dispute review, and daily SLAs','[\"customer:view\",\"astrologer:view\",\"consultation:monitor\",\"consultation:resolve\",\"ticket:manage\"]',0,'2026-11-26 14:10:02.942','2026-11-26 14:10:02.942'),('cmwxmq7gk000mn8fq9qtwq7iz','Finance Manager','FINANCE_MANAGER','Manages settlements, financial ledger, withdrawals & GST reports','[\"finance:view\",\"finance:payout_initiate\",\"finance:payout_approve\",\"finance:refund\",\"audit:view\"]',0,'2026-11-26 14:10:02.948','2026-11-26 14:10:02.948'),('cmwxmq7gu000nn8fq3ow1ihkv','Sales Executive','SALES_EXECUTIVE','Lead management, outbound devotee consultation and follow-ups','[\"lead:view\",\"lead:create\",\"lead:edit\",\"lead:convert\"]',0,'2026-11-26 14:10:02.958','2026-11-26 14:10:02.958'),('cmwxmq7h1000on8fq9jmxilb9','Customer Support Executive','SUPPORT_EXECUTIVE','Resolves helpdesk tickets, consultation quality inquiries and live chat disputes','[\"ticket:view\",\"ticket:create\",\"ticket:reply\",\"ticket:escalate\",\"customer:view\"]',0,'2026-11-26 14:10:02.965','2026-11-26 14:10:02.965'),('cmwxmq7hc000pn8fqtje1eul7','Puja & Pandit Coordinator','PANDIT_COORDINATOR','Coordinates temple pujas, assigns priests, and monitors completion proof','[\"puja:view\",\"puja:manage\",\"pandit:view\",\"pandit:assign\"]',0,'2026-11-26 14:10:02.976','2026-11-26 14:10:02.976'),('cmwxmq7j3000qn8fqlxi343be','Senior Dispute Investigator','DISP_INV_3012','Investigates customer chargebacks and approves refunds up to Rs 5000','[\"DISPUTES_READ\",\"DISPUTES_INVESTIGATE\",\"REFUNDS_APPROVE\"]',0,'2026-11-26 14:10:03.039','2026-11-26 14:10:03.039'),('cmwxn0vr3000asuh8e4jagksb','Dispute Investigator 0975','DISP_INV_0975','Investigates customer chargebacks and approves refunds up to Rs 5000','[\"DISPUTES_READ\",\"DISPUTES_INVESTIGATE\",\"REFUNDS_APPROVE\"]',0,'2026-11-26 14:18:20.991','2026-11-26 14:18:20.991'),('cmwxn2075000ak8dv75m9s21q','Dispute Investigator 3395','DISP_INV_3395','Investigates customer chargebacks and approves refunds up to Rs 5000','[\"DISPUTES_READ\",\"DISPUTES_INVESTIGATE\",\"REFUNDS_APPROVE\"]',0,'2026-11-26 14:19:13.409','2026-11-26 14:19:13.409'),('cmwxn2emc000aryuuosvxi0dc','Dispute Investigator 2094','DISP_INV_2094','Investigates customer chargebacks and approves refunds up to Rs 5000','[\"DISPUTES_READ\",\"DISPUTES_INVESTIGATE\",\"REFUNDS_APPROVE\"]',0,'2026-11-26 14:19:32.100','2026-11-26 14:19:32.100'),('cmwxn2rf3000ac4zxn91pforr','Dispute Investigator 8673','DISP_INV_8673','Investigates customer chargebacks and approves refunds up to Rs 5000','[\"DISPUTES_READ\",\"DISPUTES_INVESTIGATE\",\"REFUNDS_APPROVE\"]',0,'2026-11-26 14:19:48.687','2026-11-26 14:19:48.687');
