--
-- Table structure for table `customer_profiles`
--

DROP TABLE IF EXISTS `customer_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_profiles` (
  `id` varchar(191) NOT NULL,
  `userId` varchar(191) NOT NULL,
  `avatarUrl` varchar(512) DEFAULT NULL,
  `dateOfBirth` date DEFAULT NULL,
  `timeOfBirth` varchar(16) DEFAULT NULL,
  `isBirthTimeUnknown` tinyint(1) NOT NULL DEFAULT 0,
  `birthPlace` varchar(191) DEFAULT NULL,
  `birthLatitude` double DEFAULT NULL,
  `birthLongitude` double DEFAULT NULL,
  `birthTimezone` varchar(64) DEFAULT 'Asia/Kolkata',
  `currentCity` varchar(120) DEFAULT NULL,
  `gender` varchar(20) DEFAULT NULL,
  `maritalStatus` varchar(32) DEFAULT NULL,
  `consultationInterests` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`consultationInterests`)),
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customer_profiles_userId_key` (`userId`),
  CONSTRAINT `customer_profiles_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

