DROP TABLE IF EXISTS `dispute_complaints`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dispute_complaints` (
  `id` varchar(191) NOT NULL,
  `complaintNumber` varchar(32) NOT NULL,
  `customerId` varchar(64) NOT NULL,
  `category` enum('CONSULTATION_ISSUE','ASTROLOGER_COMPLAINT','BILLING_DISPUTE','INCORRECT_WALLET_DEDUCTION','PUJA_SERVICE_COMPLAINT','PRODUCT_AUTHENTICITY','DELIVERY_COMPLAINT','PAYOUT_DISPUTE','REPORT_QUALITY','LIVE_STREAMING','GENERAL') NOT NULL DEFAULT 'GENERAL',
  `subject` varchar(191) NOT NULL,
  `description` text NOT NULL,
  `evidenceUrlsJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`evidenceUrlsJson`)),
  `relatedConsultationId` varchar(64) DEFAULT NULL,
  `relatedOrderId` varchar(64) DEFAULT NULL,
  `relatedBookingId` varchar(64) DEFAULT NULL,
  `relatedTransactionId` varchar(64) DEFAULT NULL,
  `assignedStaffId` varchar(64) DEFAULT NULL,
  `status` enum('FILED','ASSIGNED','UNDER_INVESTIGATION','RESOLVED','REFUND_RECOMMENDED','REFUND_PROCESSED','REJECTED','APPEALED','CLOSED') NOT NULL DEFAULT 'FILED',
  `investigationNotes` text DEFAULT NULL,
  `resolutionDecision` text DEFAULT NULL,
  `refundAmountPaise` bigint(20) NOT NULL DEFAULT 0,
  `isRefundProcessed` tinyint(1) NOT NULL DEFAULT 0,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dispute_complaints_complaintNumber_key` (`complaintNumber`),
  KEY `dispute_complaints_customerId_status_idx` (`customerId`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
