CREATE TABLE `support_messages` (
  `id` varchar(191) NOT NULL,
  `ticketId` varchar(191) NOT NULL,
  `senderId` varchar(191) NOT NULL,
  `senderRole` enum('CUSTOMER','ASTROLOGER','PANDIT','SUPPORT','FINANCE','VERIFICATION','MARKETING','STAFF','BUSINESS_OWNER','SUPER_ADMIN') NOT NULL DEFAULT 'CUSTOMER',
  `message` text NOT NULL,
