--
-- Table structure for table `wallet_transactions`
--

DROP TABLE IF EXISTS `wallet_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallet_transactions` (
  `id` varchar(191) NOT NULL,
  `walletId` varchar(191) NOT NULL,
  `idempotencyKey` varchar(128) NOT NULL,
  `type` enum('WALLET_RECHARGE','PROMO_CREDIT','CONSULTATION_DEBIT','LIVE_QUESTION_DEBIT','PUJA_PAYMENT','STORE_PAYMENT','REFUND_CREDIT','ADMIN_ADJUSTMENT','CONSULTATION_HOLD','HOLD_RELEASE') NOT NULL,
  `amountPaise` bigint(20) NOT NULL,
  `balanceAfterPaise` bigint(20) NOT NULL,
  `referenceType` varchar(64) DEFAULT NULL,
  `referenceId` varchar(128) DEFAULT NULL,
  `description` varchar(255) NOT NULL,
  `metadataJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadataJson`)),
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `wallet_transactions_idempotencyKey_key` (`idempotencyKey`),
  KEY `wallet_transactions_walletId_createdAt_idx` (`walletId`,`createdAt`),
  KEY `wallet_transactions_referenceType_referenceId_idx` (`referenceType`,`referenceId`),
  CONSTRAINT `wallet_transactions_walletId_fkey` FOREIGN KEY (`walletId`) REFERENCES `wallets` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

