DROP TABLE IF EXISTS `wallets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallets` (
  `id` varchar(191) NOT NULL,
  `userId` varchar(191) NOT NULL,
  `currency` varchar(3) NOT NULL DEFAULT 'INR',
  `paidBalancePaise` bigint(20) NOT NULL DEFAULT 0,
  `promoBalancePaise` bigint(20) NOT NULL DEFAULT 0,
  `refundBalancePaise` bigint(20) NOT NULL DEFAULT 0,
  `version` int(11) NOT NULL DEFAULT 1,
  `updatedAt` datetime(3) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `wallets_userId_key` (`userId`),
  CONSTRAINT `wallets_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
